-- READ-ONLY six-archive cohort summary; SELECT only.
SELECT 'reconstruction' AS archive,8 AS gap_count,COUNT(DISTINCT gap_id) AS gaps_with_rows,8-COUNT(DISTINCT gap_id) AS gaps_without_rows,COUNT(*) AS source_rows,COUNT(DISTINCT CASE WHEN `outTemp` IS NOT NULL THEN gap_id END) AS gaps_with_outTemp, SUM(`outTemp` IS NOT NULL) AS values_outTemp, COUNT(DISTINCT CASE WHEN `outHumidity` IS NOT NULL THEN gap_id END) AS gaps_with_outHumidity, SUM(`outHumidity` IS NOT NULL) AS values_outHumidity, COUNT(DISTINCT CASE WHEN `rain` IS NOT NULL THEN gap_id END) AS gaps_with_rain, SUM(`rain` IS NOT NULL) AS values_rain, COUNT(DISTINCT CASE WHEN `rainRate` IS NOT NULL THEN gap_id END) AS gaps_with_rainRate, SUM(`rainRate` IS NOT NULL) AS values_rainRate, COUNT(DISTINCT CASE WHEN `windSpeed` IS NOT NULL THEN gap_id END) AS gaps_with_windSpeed, SUM(`windSpeed` IS NOT NULL) AS values_windSpeed, COUNT(DISTINCT CASE WHEN `windGust` IS NOT NULL THEN gap_id END) AS gaps_with_windGust, SUM(`windGust` IS NOT NULL) AS values_windGust, COUNT(DISTINCT CASE WHEN `barometer` IS NOT NULL THEN gap_id END) AS gaps_with_barometer, SUM(`barometer` IS NOT NULL) AS values_barometer FROM (SELECT CASE WHEN `dateTime`>1737698100 AND `dateTime`<1737726900 THEN 1 WHEN `dateTime`>1753792500 AND `dateTime`<1753800300 THEN 2 WHEN `dateTime`>1754653800 AND `dateTime`<1754658300 THEN 3 WHEN `dateTime`>1755168000 AND `dateTime`<1755240000 THEN 4 WHEN `dateTime`>1755496500 AND `dateTime`<1755519300 THEN 5 WHEN `dateTime`>1757604300 AND `dateTime`<1757608200 THEN 6 WHEN `dateTime`>1766086200 AND `dateTime`<1766125500 THEN 7 WHEN `dateTime`>1767206400 AND `dateTime`<1767221400 THEN 8 ELSE NULL END AS gap_id,`dateTime`,`outTemp`,`outHumidity`,`rain`,`rainRate`,`windSpeed`,`windGust`,`barometer` FROM `loucka_reconstruction`.`archive` WHERE (`dateTime`>1737698100 AND `dateTime`<1737726900) OR (`dateTime`>1753792500 AND `dateTime`<1753800300) OR (`dateTime`>1754653800 AND `dateTime`<1754658300) OR (`dateTime`>1755168000 AND `dateTime`<1755240000) OR (`dateTime`>1755496500 AND `dateTime`<1755519300) OR (`dateTime`>1757604300 AND `dateTime`<1757608200) OR (`dateTime`>1766086200 AND `dateTime`<1766125500) OR (`dateTime`>1767206400 AND `dateTime`<1767221400)) q;
